package com.cpf.education.online.concurrency.controller;
import com.cpf.education.online.concurrency.model.MemberVersion;import com.cpf.education.online.concurrency.service.MemberPreferenceService;import com.cpf.foundation.execution.api.CpfOnlineTransaction;import com.cpf.web.api.CpfRestController;import io.swagger.v3.oas.annotations.Operation;import org.springframework.web.bind.annotation.*;
/** 동시성 제어 교육 예제의 Controller 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfRestController @RequestMapping("/edu/online/member-preferences") public class MemberPreferenceController {private final MemberPreferenceService service;public MemberPreferenceController(MemberPreferenceService s){service=s;}@PutMapping @Operation(operationId="EDU_MEMBER_OPTIMISTIC_UPDATE",summary="동시성·Optimistic Lock 거래") @CpfOnlineTransaction(operationId="EDU_MEMBER_OPTIMISTIC_UPDATE",name="동시성·Optimistic Lock 거래",description="Version 기반 동시갱신 충돌을 CPF CONFLICT(409)로 분류하고 blind retry를 금지한다.") public MemberVersion update(@RequestBody MemberVersion c){return service.update(c);}}
